// Filter for postings within the last 24 hours only
const now = new Date();
const items = $input.all();
const freshJobs = [];

for (const item of items) {
  const postedAt = item.json.updated_at || item.json.posted_at;
  if (!postedAt) continue;
  const ageHours = (now.getTime() - new Date(postedAt).getTime()) / (1000 * 60 * 60);
  if (ageHours <= 24) {
    freshJobs.push({
      json: {
        title: item.json.title,
        company: 'Spryker',
        location: item.json.location ? item.json.location.name : 'Germany · Remote',
        isRemote: true,
        postedAt: postedAt,
        canonicalUrl: item.json.absolute_url,
        applicationUrl: item.json.absolute_url,
        source: 'Greenhouse Public Board',
        techStack: ['PHP', 'Laravel', 'Vue.js', 'Docker', 'AWS']
      }
    });
  }
}
return freshJobs;
